create table if not exists public.school_roles (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  name text not null check (char_length(trim(name)) between 2 and 80),
  description text,
  is_system boolean not null default false,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  unique (school_id, name)
);
create table if not exists public.school_role_permissions (
  role_id uuid not null references public.school_roles(id) on delete cascade,
  permission text not null check (permission in ('students.view','students.manage','registrations.manage','classes.manage','attendance.manage','grades.manage','payments.view','payments.manage','documents.manage','calendar.manage','users.manage','roles.manage')),
  created_at timestamptz not null default now(),
  primary key (role_id, permission)
);
create table if not exists public.school_member_custom_roles (
  school_id uuid not null references public.schools(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  role_id uuid not null references public.school_roles(id) on delete cascade,
  assigned_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  primary key (school_id, user_id, role_id)
);
create index if not exists school_roles_school_idx on public.school_roles(school_id);
create index if not exists school_member_custom_roles_lookup_idx on public.school_member_custom_roles(school_id, user_id);

create or replace function schooly_private.can_manage_roles(target_school_id uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.school_memberships where school_id = target_school_id and user_id = auth.uid() and role in ('owner','director','administrator'));
$$;
create or replace function schooly_private.has_school_permission(target_school_id uuid, required_permission text) returns boolean language sql stable security definer set search_path = public as $$
  select schooly_private.can_manage_roles(target_school_id)
    or exists (select 1 from public.school_memberships where school_id = target_school_id and user_id = auth.uid() and ((role = 'accountant' and required_permission in ('payments.view','payments.manage')) or (role = 'secretary' and required_permission in ('students.view','students.manage','registrations.manage')) or (role = 'teacher' and required_permission in ('attendance.manage','grades.manage','students.view'))))
    or exists (select 1 from public.school_member_custom_roles assignment join public.school_role_permissions permission on permission.role_id = assignment.role_id where assignment.school_id = target_school_id and assignment.user_id = auth.uid() and permission.permission = required_permission);
$$;
grant execute on function schooly_private.can_manage_roles(uuid) to authenticated;
grant execute on function schooly_private.has_school_permission(uuid, text) to authenticated;

alter table public.school_roles enable row level security;
alter table public.school_role_permissions enable row level security;
alter table public.school_member_custom_roles enable row level security;
create policy school_roles_read_member on public.school_roles for select to authenticated using (schooly_private.is_approved_school_member(school_id));
create policy school_roles_manage_leader on public.school_roles for all to authenticated using (schooly_private.can_manage_roles(school_id)) with check (schooly_private.can_manage_roles(school_id));
create policy school_role_permissions_read_member on public.school_role_permissions for select to authenticated using (exists (select 1 from public.school_roles role_item where role_item.id = role_id and schooly_private.is_approved_school_member(role_item.school_id)));
create policy school_role_permissions_manage_leader on public.school_role_permissions for all to authenticated using (exists (select 1 from public.school_roles role_item where role_item.id = role_id and schooly_private.can_manage_roles(role_item.school_id))) with check (exists (select 1 from public.school_roles role_item where role_item.id = role_id and schooly_private.can_manage_roles(role_item.school_id)));
create policy school_custom_roles_read_member on public.school_member_custom_roles for select to authenticated using (schooly_private.is_approved_school_member(school_id));
create policy school_custom_roles_manage_leader on public.school_member_custom_roles for all to authenticated using (schooly_private.can_manage_roles(school_id)) with check (schooly_private.can_manage_roles(school_id));

drop policy if exists payments_approved_member_access on public.payments;
create policy payments_read_approved_member on public.payments for select to authenticated using (schooly_private.is_approved_school_member(school_id));
create policy payments_create_permitted_role on public.payments for insert to authenticated with check (schooly_private.has_school_permission(school_id, 'payments.manage'));
create policy payments_update_permitted_role on public.payments for update to authenticated using (schooly_private.has_school_permission(school_id, 'payments.manage')) with check (schooly_private.has_school_permission(school_id, 'payments.manage'));
create policy payments_delete_permitted_role on public.payments for delete to authenticated using (schooly_private.has_school_permission(school_id, 'payments.manage'));
